// src/Telas/Detalhes.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../Estilo/Detalhes.css'; // Caminho para o CSS atualizado

function Detalhes() {
  const [data, setData] = useState([]);

  // useEffect para buscar os dados ao inicializar a tela
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get('https://requestuser.free.beeceptor.com');
        console.log('Dados recebidos:', response.data);

        if (Array.isArray(response.data)) {
          setData(response.data);
        } else {
          console.error('A resposta não é um array:', response.data);
          setData([]);  // Defina data como um array vazio para evitar erros
        }
      } catch (error) {
        console.error('Ocorreu um erro ao buscar os dados:', error);
        setData([]);  // Defina data como um array vazio em caso de erro
      }
    };

    fetchData();
  }, []);

  console.log('Estado data:', data);

  return (
    <div className="App min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="w-full max-w-md p-6 bg-white rounded-lg shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Detalhes do Cadastro</h1>

        {/* Renderização condicional para verificar se há dados */}
        {data.length > 0 ? (
          data.map((item, index) => (
            <div key={index} className="card">
              <p><strong>Nome Completo:</strong> {item.nomeCompleto}</p>
              <p><strong>Data de Nascimento:</strong> {item.dataNascimento}</p>
              <p><strong>Telefone:</strong> {item.telefone}</p>
            </div>
          ))
        ) : (
          <p>Nenhum dado disponível</p>
        )}
      </div>
    </div>
  );
}

export default Detalhes;
